import com.project.system.service.WalletService;import java.math.BigDecimal;import java.util.*;import org.springframework.context.annotation.AnnotationConfigApplicationContext;import org.springframework.jdbc.core.JdbcTemplate;
public class TransactionNumberIntegration{public static void main(String[]args){try(AnnotationConfigApplicationContext c=new AnnotationConfigApplicationContext(WalletIdentityIntegration.Config.class)){WalletService s=c.getBean(WalletService.class);JdbcTemplate db=c.getBean(JdbcTemplate.class);String key=UUID.randomUUID().toString();long id=s.trade(2,"PAY",new BigDecimal("0.01"),3L,null,key,1);String number=(String)s.receipt(id).get("transaction_no");String expected=db.queryForObject("select concat('XF',date_format(created_at,'%Y%m%d%H%i%s'),'-',lpad(cast(id as char),20,'0')) from campus_ledger where id=?",String.class,id);if(!number.equals(expected))throw new AssertionError();System.out.println("PASS number matches transaction time and unique sequence");long repeat=s.trade(2,"PAY",new BigDecimal("0.01"),3L,null,key,1);if(repeat!=id||!number.equals(s.receipt(repeat).get("transaction_no")))throw new AssertionError();System.out.println("PASS retry preserves accounting number");if(db.queryForObject("select count(*)-count(distinct transaction_no) from campus_ledger",Integer.class)!=0)throw new AssertionError();System.out.println("PASS existing and new numbers unique");}}}
